const catalog = [
  {id:'poon-hill',name:'Poon Hill',region:'Gandaki, Nepal',category:'mountains',difficulty:'Moderate',length:'5 days',description:'Golden sunrise above the Annapurna range.',image:'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=900&q=85'},
  {id:'everest-base-camp',name:'Everest Base Camp',region:'Khumbu, Nepal',category:'mountains',difficulty:'Challenging',length:'12 days',description:'A journey through the heart of the Himalayas.',image:'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=900&q=85'},
  {id:'lake-bled',name:'Lake Bled Loop',region:'Upper Carniola, Slovenia',category:'forests',difficulty:'Easy',length:'6 km',description:'Lakeside calm beneath the Julian Alps.',image:'https://images.unsplash.com/photo-1519681393784-d120267933ba?w=900&q=85'},
  {id:'annapurna',name:'Annapurna Circuit',region:'Gandaki, Nepal',category:'mountains',difficulty:'Challenging',length:'16 days',description:'High passes and villages with stories to tell.',image:'https://images.unsplash.com/photo-1470770841072-f978cf4d019e?w=900&q=85'},
  {id:'cinque-terre',name:'Cinque Terre Trail',region:'Liguria, Italy',category:'coast',difficulty:'Moderate',length:'11 km',description:'Colorful villages along a bright blue coast.',image:'https://images.unsplash.com/photo-1498307833015-e7b400441eb8?w=900&q=85'},
  {id:'muir-woods',name:'Muir Woods',region:'California, USA',category:'forests',difficulty:'Easy',length:'4 km',description:'A quiet walk under ancient redwoods.',image:'https://images.unsplash.com/photo-1448375240586-882707db888b?w=900&q=85'},
  {id:'langtang',name:'Langtang Valley',region:'Bagmati, Nepal',category:'mountains',difficulty:'Moderate',length:'8 days',description:'Wide valleys and welcoming mountain villages.',image:'https://images.unsplash.com/photo-1454496522488-7a8e488e8606?w=900&q=85'},
  {id:'amalfi',name:'Path of the Gods',region:'Amalfi Coast, Italy',category:'coast',difficulty:'Moderate',length:'8 km',description:'A cliffside path above the Mediterranean.',image:'https://images.unsplash.com/photo-1533105079780-92b9be482077?w=900&q=85'},
  {id:'black-forest',name:'Black Forest',region:'Baden-Württemberg, Germany',category:'forests',difficulty:'Easy',length:'12 km',description:'Soft light through deep green woodland.',image:'https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?w=900&q=85'}
];

const $ = (selector) => document.querySelector(selector);
const state = { view:'discover', filter:'all', search:'', entries:[], saved:new Set(JSON.parse(localStorage.getItem('roam-saved') || '[]')) };
let db;
let toastTimer;

function escapeHtml(value){return String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function localDate(){const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10);}
function makeId(){return typeof crypto.randomUUID === 'function' ? crypto.randomUUID() : `visit-${Date.now()}-${Math.random().toString(36).slice(2)}`;}
function notify(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200);}
function openDatabase(){return new Promise((resolve,reject)=>{const request=indexedDB.open('roam-journal',1);request.onupgradeneeded=()=>request.result.createObjectStore('entries',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
function storeTransaction(mode, operation){return new Promise((resolve,reject)=>{const tx=db.transaction('entries',mode);const store=tx.objectStore('entries');let result;const request=operation(store);if(request){request.onsuccess=()=>result=request.result;request.onerror=()=>reject(request.error);}tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);});}
async function loadEntries(){state.entries=await storeTransaction('readonly',store=>store.getAll());render();}
async function putEntry(entry){await storeTransaction('readwrite',store=>store.put(entry));await loadEntries();}
async function removeEntry(id){await storeTransaction('readwrite',store=>store.delete(id));await loadEntries();}
function catalogForName(name){return catalog.find(place=>place.name.toLowerCase()===name.trim().toLowerCase());}
function visitFor(place){return state.entries.filter(entry=>entry.name.toLowerCase()===place.name.toLowerCase()).sort((a,b)=>b.date.localeCompare(a.date))[0];}
function toggleSaved(id){state.saved.has(id)?state.saved.delete(id):state.saved.add(id);localStorage.setItem('roam-saved',JSON.stringify([...state.saved]));render();notify(state.saved.has(id)?'Added to saved places':'Removed from saved places');}
function setView(view){state.view=view;state.search='';$('#search-input').value='';document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#breadcrumb-current').textContent=view==='visited'?'My journeys':view==='saved'?'Saved places':'Discover';const titles={discover:'Places to explore',visited:'My journeys',saved:'Saved for later'};const subtitles={discover:'From quiet paths to sky-high views, your next favorite place is out there.',visited:'Every place has a story. Here are yours.',saved:'The places calling your name, all in one spot.'};$('#section-title').innerHTML=titles[view]+'<span>.</span>';$('#section-subtitle').textContent=subtitles[view];$('#view-journeys').textContent=view==='visited'?'Explore places ↗':'View my journeys ↗';$('#intro').style.display=view==='discover'?'':'none';$('.hero').style.display=view==='discover'?'':'none';render();}
function render(){const uniquePlaces=new Set(state.entries.map(e=>e.name.toLowerCase()));$('#stat-places').textContent=uniquePlaces.size;$('#stat-regions').textContent=new Set(state.entries.map(e=>e.region.toLowerCase())).size;$('#stat-photos').textContent=state.entries.filter(e=>e.photo).length;$('#nav-count').textContent=state.entries.length;
  let items=state.view==='visited'?[...state.entries].sort((a,b)=>b.date.localeCompare(a.date)).map(e=>({...e,isEntry:true})):catalog.filter(p=>state.view!=='saved'||state.saved.has(p.id));
  if(state.view==='saved'){const custom=state.entries.filter(e=>state.saved.has(e.id)).map(e=>({...e,isEntry:true}));items=[...custom,...items];}
  if(state.filter!=='all')items=items.filter(item=>item.category===state.filter);
  if(state.search){const q=state.search.toLowerCase();items=items.filter(item=>`${item.name} ${item.region} ${item.description||''} ${item.notes||''}`.toLowerCase().includes(q));}
  $('#cards').innerHTML=items.map(cardHtml).join('');const empty=items.length===0;$('#empty-state').hidden=!empty;if(empty){const msg=state.search?'No trails found':state.view==='visited'?'Your journey starts here':state.view==='saved'?'Nothing saved yet':'No places in this category';$('#empty-title').textContent=msg;$('#empty-copy').textContent=state.search?'Try another search, or add a place of your own.':state.view==='visited'?'Add your first visited place and capture the memory.':state.view==='saved'?'Tap the heart on any place you want to explore.':'Try a different landscape or add a place of your own.';}
}
function cardHtml(item){const visit=item.isEntry?item:visitFor(item);const image=item.photo||item.image||(catalogForName(item.name)||{}).image||'./hero.png';const saved=state.saved.has(item.id);const label=item.isEntry?'Visited':item.category==='mountains'?'Mountain trail':item.category==='forests'?'Forest walk':'Coastal path';const description=item.isEntry?(item.notes||'A place worth remembering.') :item.description;const rating=item.isEntry?`<b>${'★'.repeat(Number(item.rating)||5)}</b>`:`<span>⌁ ${escapeHtml(item.length)}</span>`;return `<article class="place-card"><div class="card-image"><img src="${escapeHtml(image)}" alt="${escapeHtml(item.name)}" loading="lazy" onerror="this.onerror=null;this.src='./hero.png'"><span class="card-badge">${escapeHtml(label)}</span><button class="card-save ${saved?'saved':''}" data-action="save" data-id="${escapeHtml(item.id)}" aria-label="${saved?'Remove from':'Add to'} saved places">${saved?'♥':'♡'}</button></div><div class="card-body"><div class="card-region">⌖ ${escapeHtml(item.region)}</div><div class="card-title"><h3>${escapeHtml(item.name)}</h3><span class="arrow">↗</span></div><p class="card-description">${escapeHtml(description)}</p><div class="card-footer"><div class="card-meta">${rating}<span>·</span><span>${item.isEntry?escapeHtml(new Date(item.date+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})):escapeHtml(item.difficulty)}</span></div><div class="card-actions">${item.isEntry?`<button class="card-action" data-action="edit" data-id="${escapeHtml(item.id)}">Edit</button><button class="card-action delete" data-action="delete" data-id="${escapeHtml(item.id)}">Delete</button>`:`<button class="card-action" data-action="log" data-id="${escapeHtml(item.id)}">${visit?'Visit again':'Mark visited'} ↗</button>`}</div></div></div></article>`;}
function resetPreview(){const img=$('#photo-preview');img.hidden=true;img.removeAttribute('src');$('#upload-title').textContent='Add your best capture';$('#upload-subtitle').textContent='Choose a photo from your device · JPG, PNG, WebP';}
function openEntry(place=null,entry=null){$('#entry-form').reset();$('#entry-id').value=entry?.id||'';$('#dialog-title').innerHTML=(entry?'Edit journey':'Add a journey')+'<span>.</span>';$('#save-button').innerHTML=(entry?'Save changes':'Save journey')+' <span>↗</span>';$('#visit-date').value=entry?.date||localDate();$('#place-name').value=entry?.name||place?.name||'';$('#place-region').value=entry?.region||place?.region||'';$('#place-category').value=entry?.category||place?.category||'mountains';$('#place-rating').value=String(entry?.rating||5);$('#place-notes').value=entry?.notes||'';resetPreview();if(entry?.photo){$('#photo-preview').src=entry.photo;$('#photo-preview').hidden=false;$('#upload-title').textContent='Replace your capture';$('#upload-subtitle').textContent='Your current photo is saved';}$('#entry-dialog').showModal();setTimeout(()=>$('#place-name').focus(),50);}
async function compressImage(file){if(!file.type.startsWith('image/'))throw new Error('Choose an image file.');if(file.size>20*1024*1024)throw new Error('Please choose an image smaller than 20 MB.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return canvas.toDataURL('image/jpeg',.84);}
async function saveForm(event){event.preventDefault();const name=$('#place-name').value.trim(),region=$('#place-region').value.trim(),date=$('#visit-date').value;if(!name||!region||!date){notify('Add a place, region, and visit date.');return;}const id=$('#entry-id').value||makeId();const previous=state.entries.find(e=>e.id===id);const button=$('#save-button');button.disabled=true;try{const file=$('#place-photo').files[0];const photo=file?await compressImage(file):previous?.photo||null;await putEntry({id,name,region,date,category:$('#place-category').value,rating:Number($('#place-rating').value),notes:$('#place-notes').value.trim(),photo,updatedAt:new Date().toISOString()});$('#entry-dialog').close();setView('visited');notify(previous?'Journey updated':'Journey added to your journal');}catch(error){notify(error.message||'Could not save this journey.');}finally{button.disabled=false;}}
function exportJournal(){const data={app:'roam-journal',version:1,exportedAt:new Date().toISOString(),entries:state.entries,saved:[...state.saved]};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`roam-journal-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Journal backup downloaded');}
async function importJournal(file){try{const data=JSON.parse(await file.text());if(data.app!=='roam-journal'||!Array.isArray(data.entries))throw new Error('This is not a Roam journal backup.');let count=0;for(const raw of data.entries){if(!raw||typeof raw.name!=='string'||typeof raw.region!=='string'||typeof raw.date!=='string'||!raw.name.trim()||!raw.region.trim())continue;const entry={id:typeof raw.id==='string'?raw.id:makeId(),name:raw.name.slice(0,80),region:raw.region.slice(0,80),date:raw.date.slice(0,10),category:['mountains','forests','coast'].includes(raw.category)?raw.category:'mountains',rating:Math.min(5,Math.max(1,Number(raw.rating)||5)),notes:String(raw.notes||'').slice(0,500),photo:typeof raw.photo==='string'&&raw.photo.startsWith('data:image/')?raw.photo:null,updatedAt:raw.updatedAt||new Date().toISOString()};await storeTransaction('readwrite',store=>store.put(entry));count++;}if(Array.isArray(data.saved)){for(const id of data.saved)if(typeof id==='string')state.saved.add(id);localStorage.setItem('roam-saved',JSON.stringify([...state.saved]));}await loadEntries();setView('visited');notify(`Imported ${count} journey${count===1?'':'s'}`);}catch(error){notify(error.message||'Could not import this backup.');}finally{$('#import-file').value='';}}

document.addEventListener('DOMContentLoaded',async()=>{const date=new Date();$('#today-label').textContent=date.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric',year:'numeric'});$('#place-suggestions').innerHTML=catalog.map(p=>`<option value="${escapeHtml(p.name)}"></option>`).join('');$('#place-name').addEventListener('change',()=>{const match=catalogForName($('#place-name').value);if(match){if(!$('#place-region').value)$('#place-region').value=match.region;$('#place-category').value=match.category;}});$('#place-photo').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const photo=await compressImage(file);$('#photo-preview').src=photo;$('#photo-preview').hidden=false;$('#upload-title').textContent=file.name;$('#upload-subtitle').textContent='Ready to save';}catch(error){e.target.value='';notify(error.message);}});
  document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{state.filter=b.dataset.filter;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===b));render();}));$('#search-input').addEventListener('input',e=>{state.search=e.target.value.trim();render();});for(const selector of ['#sidebar-add','#top-add','#hero-add','#empty-add'])$(selector).addEventListener('click',()=>openEntry());$('#view-journeys').addEventListener('click',()=>setView(state.view==='visited'?'discover':'visited'));$('#cards').addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button)return;const {action,id}=button.dataset;if(action==='save')toggleSaved(id);if(action==='log')openEntry(catalog.find(p=>p.id===id));if(action==='edit')openEntry(null,state.entries.find(x=>x.id===id));if(action==='delete'){const entry=state.entries.find(x=>x.id===id);if(entry&&confirm(`Delete your visit to ${entry.name}?`)){await removeEntry(id);notify('Journey deleted');}}});$('#entry-form').addEventListener('submit',saveForm);$('#dialog-close').addEventListener('click',()=>$('#entry-dialog').close());$('#cancel-button').addEventListener('click',()=>$('#entry-dialog').close());$('#entry-dialog').addEventListener('click',e=>{if(e.target===$('#entry-dialog'))$('#entry-dialog').close();});$('#export-button').addEventListener('click',exportJournal);$('#footer-export').addEventListener('click',exportJournal);$('#import-button').addEventListener('click',()=>$('#import-file').click());$('#import-file').addEventListener('change',e=>{if(e.target.files[0])importJournal(e.target.files[0]);});
  try{db=await openDatabase();await loadEntries();}catch(error){notify('Browser storage is unavailable. Your journal cannot be saved here.');console.error(error);render();}
});
